from shelf import books, cli, export


def setup_function():
    books.clear()


def test_export_empty_shelf():
    assert export.export_csv() == "title,author\n"


def test_export_two_books():
    books.add("Dune", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert export.export_csv() == "title,author\nDune,Frank Herbert\nEmma,Jane Austen\n"


def test_export_escapes_comma_and_quote():
    books.add('Me, "Myself"', "X")
    assert export.export_csv() == 'title,author\n"Me, ""Myself""",X\n'


def test_cli_export_prints_header(capsys):
    assert cli.main(["export"]) == 0
    assert capsys.readouterr().out == "title,author\n"
